import sys


def check_digit(digits):
    total = 0
    for i, ch in enumerate(digits):
        if i % 2 == 0:
            total += int(ch) * 3
        else:
            total += int(ch)
    return 10 - total % 10


def fmt(digits):
    return f"756.{digits[0:4]}.{digits[4:8]}.{digits[8:12]}"


def main():
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        cleaned = "".join(c for c in line if c.isdigit())
        if len(cleaned) != 13 and len(cleaned) != 12:
            print("ERROR")
            continue
        if len(cleaned) == 13 and cleaned.startswith("756"):
            if check_digit(cleaned[:12]) == int(cleaned[12]):
                print("VALID", fmt(cleaned))
            else:
                print("INVALID", check_digit(cleaned[:12]))
        elif len(cleaned) == 12 and cleaned.startswith("756"):
            check = check_digit(cleaned)
            full = cleaned + str(check)
            print("COMPLETE", fmt(full))
        else:
            print("ERROR")


if __name__ == "__main__":
    main()
